// The chalet's chat: a Netlify function at /api/chat.
// Holds the Anthropic key server-side (ANTHROPIC_API_KEY in Netlify environment variables, never in this repo),
// gives the model the site's own facts (kb.mjs, generated by build.py), lets it check the live calendar
// and build a pre-filled inquiry link, and streams the answer back as server-sent events.
// Nothing about the conversation is stored.

import { KB } from "./kb.mjs";

const MODEL = process.env.CHAT_MODEL || "claude-haiku-5-5";
const MAX_TOKENS = 450;
const MAX_TURNS = 12;
const ALLOWED = /^https:\/\/(([a-z0-9-]+--)?yosemite-gateway-chalet\.netlify\.app|(www\.)?yosemitechalet\.us|(www\.)?yosemitegatewaychalet\.com)$/;

// Best-effort limit per visitor per warm instance. The Anthropic spend cap is the hard ceiling.
const hits = new Map();
function limited(ip) {
  const now = Date.now(), win = 10 * 60 * 1000, max = 25;
  const h = (hits.get(ip) || []).filter((t) => now - t < win);
  h.push(now); hits.set(ip, h);
  if (hits.size > 5000) hits.clear();
  return h.length > max;
}

const TOOLS = [
  {
    name: "check_dates",
    description: "Check the chalet's live calendar (merged from Airbnb and VRBO, refreshed every 15 minutes) for a stay. Use whenever the guest names dates. Arrival and departure are YYYY-MM-DD; departure is the checkout day.",
    input_schema: { type: "object", properties: { arrival: { type: "string" }, departure: { type: "string" } }, required: ["arrival", "departure"] },
  },
  {
    name: "inquiry_link",
    description: "Make a link to the site's inquiry form with the guest's dates, headcount and a short starter message filled in. Use when the guest wants to book or ask the owners about dates.",
    input_schema: {
      type: "object",
      properties: { arrival: { type: "string" }, departure: { type: "string" }, guests: { type: "integer", minimum: 1, maximum: 8 }, note: { type: "string", description: "One short line for the message box, in the guest's words, e.g. who is coming and what they want to do." } },
    },
  },
];

const isoOk = (s) => /^\d{4}-\d{2}-\d{2}$/.test(s || "") && !isNaN(Date.parse(s));

async function runTool(name, input, origin) {
  if (name === "check_dates") {
    const { arrival, departure } = input || {};
    if (!isoOk(arrival) || !isoOk(departure) || departure <= arrival) return { error: "Need a valid arrival and a later departure, as YYYY-MM-DD." };
    const today = new Date().toISOString().slice(0, 10);
    if (arrival < today) return { error: "Those dates are in the past." };
    try {
      const r = await fetch(`${origin}/api/availability`, { signal: AbortSignal.timeout(6000) });
      const j = await r.json();
      if (!r.ok || !j.booked) return { status: "unknown", note: "The calendar is not answering right now. Send them to the inquiry form." };
      const clash = j.booked.filter(([s, e]) => s < departure && e > arrival);
      return {
        status: clash.length ? "booked" : "open",
        nights: Math.round((Date.parse(departure) - Date.parse(arrival)) / 864e5),
        booked_nights_overlapping: clash,
        calendar_complete: j.complete,
        checked: j.updated,
        reminder: "Open on the calendar is not a confirmed booking. Only the owners confirm, through the form.",
      };
    } catch {
      return { status: "unknown", note: "The calendar is not answering right now. Send them to the inquiry form." };
    }
  }
  if (name === "inquiry_link") {
    const q = new URLSearchParams();
    if (isoOk(input?.arrival)) q.set("arrival", input.arrival);
    if (isoOk(input?.departure)) q.set("departure", input.departure);
    const g = parseInt(input?.guests, 10); if (g >= 1 && g <= 8) q.set("guests", String(g));
    if (input?.note) q.set("message", String(input.note).slice(0, 300));
    const qs = q.toString();
    return { url: `/inquire/${qs ? "?" + qs : ""}#inquiry-form`, how_to_share: "Give it as a markdown link, e.g. [Send your inquiry](URL)." };
  }
  return { error: "unknown tool" };
}

function cleanMessages(raw) {
  if (!Array.isArray(raw)) return null;
  const msgs = raw.slice(-MAX_TURNS)
    .filter((m) => m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string" && m.content.trim())
    .map((m) => ({ role: m.role, content: m.content.slice(0, m.role === "user" ? 600 : 1500) }));
  while (msgs.length && msgs[0].role !== "user") msgs.shift();
  if (!msgs.length || msgs[msgs.length - 1].role !== "user") return null;
  return msgs;
}

const sse = (obj) => `data: ${JSON.stringify(obj)}\n\n`;

export default async (req, context) => {
  if (req.method !== "POST") return new Response("Method not allowed", { status: 405 });
  const origin = req.headers.get("origin") || "";
  const site = new URL(req.url).origin;
  if (origin && !ALLOWED.test(origin) && origin !== site) return new Response("Forbidden", { status: 403 });
  const key = (process.env.ANTHROPIC_API_KEY || "").trim().replace(/^["']|["']$/g, "");
  if (!key) return Response.json({ message: "The chat is getting set up. Back shortly. Meanwhile the [inquiry form](/inquire/) works, and the owners answer within a day." }, { status: 503 });
  if (limited(context.ip || req.headers.get("x-nf-client-connection-ip") || "anon")) {
    return Response.json({ message: "That's a lot of questions. Take a breather, look around, and try again in a few minutes. The [inquiry form](/inquire/) is always open." }, { status: 429 });
  }
  let body;
  try { body = await req.json(); } catch { return new Response("Bad request", { status: 400 }); }
  const messages = cleanMessages(body.messages);
  if (!messages) return new Response("Bad request", { status: 400 });
  const page = typeof body.page === "string" ? body.page.slice(0, 120) : "/";

  const today = new Date().toLocaleDateString("en-US", { timeZone: "America/Los_Angeles", weekday: "long", year: "numeric", month: "long", day: "numeric" });
  const system = [
    { type: "text", text: KB.voice },
    { type: "text", text: KB.facts.replace("{TODAY}", today), cache_control: { type: "ephemeral" } },
    { type: "text", text: `The guest is reading ${page} right now.` },
  ];

  const enc = new TextEncoder();
  const stream = new ReadableStream({
    async start(ctrl) {
      const send = (o) => ctrl.enqueue(enc.encode(sse(o)));
      let convo = messages;
      try {
        for (let round = 0; round < 3; round++) {
          const r = await fetch("https://api.anthropic.com/v1/messages", {
            method: "POST",
            headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
            body: JSON.stringify({ model: MODEL, max_tokens: MAX_TOKENS, system, tools: TOOLS, messages: convo, stream: true }),
            signal: AbortSignal.timeout(25000),
          });
          if (!r.ok || !r.body) {
            console.error("anthropic", r.status, (await r.text()).slice(0, 300));
            send({ t: "Line's down for a minute. The [inquiry form](/inquire/) still works, and the owners answer within a day." });
            break;
          }
          // Read Anthropic's event stream: pass text through, collect any tool calls
          const reader = r.body.getReader(), dec = new TextDecoder();
          let buf = "", stop = null;
          const blocks = [];
          for (;;) {
            const { value, done } = await reader.read();
            if (done) break;
            buf += dec.decode(value, { stream: true });
            let i;
            while ((i = buf.indexOf("\n\n")) >= 0) {
              const chunk = buf.slice(0, i); buf = buf.slice(i + 2);
              const data = chunk.split("\n").find((l) => l.startsWith("data: "));
              if (!data) continue;
              let ev; try { ev = JSON.parse(data.slice(6)); } catch { continue; }
              if (ev.type === "content_block_start") {
                const b = ev.content_block;
                blocks[ev.index] = b.type === "tool_use" ? { type: "tool_use", id: b.id, name: b.name, json: "" } : { type: "text", text: "" };
              } else if (ev.type === "content_block_delta") {
                const b = blocks[ev.index];
                if (ev.delta.type === "text_delta") { b.text += ev.delta.text; send({ t: ev.delta.text }); }
                else if (ev.delta.type === "input_json_delta") b.json += ev.delta.partial_json;
              } else if (ev.type === "message_delta") {
                stop = ev.delta.stop_reason;
              }
            }
          }
          const tools = blocks.filter((b) => b && b.type === "tool_use");
          if (stop !== "tool_use" || !tools.length) break;
          // Run the tools, then let the model finish the answer
          const assistant = blocks.filter(Boolean).map((b) => b.type === "text"
            ? { type: "text", text: b.text || " " }
            : { type: "tool_use", id: b.id, name: b.name, input: (() => { try { return JSON.parse(b.json || "{}"); } catch { return {}; } })() });
          const results = [];
          for (const t of assistant.filter((b) => b.type === "tool_use")) {
            results.push({ type: "tool_result", tool_use_id: t.id, content: JSON.stringify(await runTool(t.name, t.input, site)) });
          }
          const textSoFar = assistant.filter((b) => b.type === "text").map((b) => b.text).join("").trim();
          if (textSoFar) send({ t: "\n\n" });
          convo = [...convo, { role: "assistant", content: assistant.filter((b) => b.type === "tool_use" || b.text.trim()) }, { role: "user", content: results }];
        }
      } catch (e) {
        console.error("chat", e && e.message);
        send({ t: "Line's down for a minute. The [inquiry form](/inquire/) still works, and the owners answer within a day." });
      }
      send({ done: true });
      ctrl.close();
    },
  });
  return new Response(stream, { headers: { "content-type": "text/event-stream; charset=utf-8", "cache-control": "no-store", "x-content-type-options": "nosniff" } });
};

export const config = { path: "/api/chat" };
